// Normalize webhook input - handle different payload formats
let input = $json;

// If data is nested in 'body' (raw body mode), extract it
if (input.body && typeof input.body === 'string') {
  try {
    input = JSON.parse(input.body);
  } catch(e) {}
} else if (input.body && typeof input.body === 'object') {
  input = input.body;
}

// Extract fields
let githubUrl = input.github_url || '';
let filename = input.filename || '';
let student_name = input.student_name || 'Estudiante';

// Convert github_url to raw_url
let rawUrl = '';
if (githubUrl) {
  rawUrl = githubUrl.replace(/github\.com\/([\w-]+\/[\w-]+)(\/.+|$)/, 'raw.githubusercontent.com/$1/main$2') + '/' + filename;
}

return [{ json: { student_name, filename, github_url: githubUrl, raw_url: rawUrl } }];

// 1. Preparar los datos
const raw = $json;
const cells = raw.cells || [];
const student_name = $('Normaliza entrada webhook').item.json.student_name || "Estudiante";
const filename = $('Normaliza entrada webhook').item.json.filename || "notebook.ipynb";

// 2. Sanitización
let cleanText = [];
for (let i = 0; i < cells.length; i++) {
    const cell = cells[i];
    const cellType = cell.cell_type || "unknown";
    let code = "";
    if (Array.isArray(cell.source)) { code = cell.source.join(""); } else { code = String(cell.source); }
    cleanText.push(`--- Celda ${i+1} (${cellType}) ---`);
    cleanText.push(code.trim());
    if (cellType === "code") {
        const outputs = cell.outputs || [];
        if (outputs.length > 0) {
            cleanText.push("## OUTPUTS:");
            for (let out of outputs) {
                if (out.data && (out.data["image/png"] || out.data["image/jpeg"])) { continue; }
                let text = "";
                if (out.output_type === "stream") { text = out.text || ""; }
                else if (out.data && out.data["text/plain"]) { text = out.data["text/plain"].join(""); }
                if (text) {
                    if (text.length > 800) { text = text.substring(0, 800) + "\n... [Output truncado] ..."; }
                    cleanText.push(text);
                }
            }
        }
    }
}

// 3. Unir y truncar
let cleanedNotebook = cleanText.join("\n");
if (cleanedNotebook.length > 15000) {
    cleanedNotebook = cleanedNotebook.substring(0, 15000) + "\n\n[Nota: Notebook muy largo, se ha truncado el final]";
}

// 4. Identificar tarea desde el contenido del notebook
let taskKey = "default";
const lowerText = cleanedNotebook.toLowerCase();
if (lowerText.includes("numpy")) {
    if (lowerText.includes("structured array") || lowerText.includes("broadcasting") || lowerText.includes("eigenvalue") || lowerText.includes("polynomial")) {
        taskKey = "numpy_ii";
    } else {
        taskKey = "numpy_i";
    }
} else if (lowerText.includes("pandas")) { taskKey = "pandas_i"; }
else if (lowerText.includes("matplotlib")) { taskKey = "matplotlib_i"; }
else if (lowerText.includes("scikit")) { taskKey = "scikit_i"; }

// 5. Retornar
return [{json: {cleaned_notebook: cleanedNotebook, student_name: student_name, filename: filename, task_key: taskKey}}];

const cleanedNotebook = $json.cleaned_notebook;
const student_name = $json.student_name;
const filename = $json.filename;
const rubricContent = $json.rubric_content || "Evalúa usando criterios generales: completitud, corrección y uso adecuado de la librería.";

const prompt = `${rubricContent}

### EVALUATION INSTRUCTIONS:
First make sure to find out how many questions there are in the notebook and check every one has at least one code cell as an answer, so you can see if there are unresolved exercises. If there is no python code in the solution, the exercise is probably unresolved. Be sure to go one by one, reading carefully.
If the answer is present, evaluate it based on the rubric criteria above.
Solving a problem in more than one way is a plus, as long as all the answers are correct.
Check if the code is correct by running it in your mind, step by step. If you find any mistake, note it down.

### REPORT FORMAT:
Structure the final report in spanish as follows:
- Title of the report, with the name of the student and the file name of the document.
- Global grade of the notebook according to this Grade Scale:
    - 'Mal': Tasks are not understood, more than half of the exercises are unresolved, severe issues.
    - 'Regular': Many issues with task understanding, code correctness or syntax.
    - 'Bien': Good task understanding, code mostly functional with minor issues.
    - 'Excepcional': No major issues; code is clean and fully functional.
- Summary of global main factors performance.
- Summary of global secondary factors performance.
- List of exercises with issues (table format: Nº | Ejercicio | Problema | Recomendación).

Here is the notebook to review:
**Alumno:** ${student_name}
**Archivo:** ${filename}
**Contenido (Limpio):**
${cleanedNotebook}`;

return [{json: {prompt: prompt, student_name, filename}}];

