// 1. Obtener la respuesta
const response = $json;
const msg = response.choices[0].message;

// Priorizar 'content'. Si está vacío, usar 'reasoning_content' como fallback
let rawText = msg.content || msg.reasoning_content || "";

// 2. Buscar la calificación (más flexible)
let gradeText = "Regular";
const match = rawText.match(/(?:Calificación Global|Nota)[,:]\s*\**\**?(Mal|Regular|Bien|Excepcional)/i);
if (match) gradeText = match[1];

// 3. Mapear a nota numérica
const gradeMap = { "Mal": 3, "Regular": 5, "Bien": 7, "Excepcional": 9 };
const numericGrade = gradeMap[gradeText] || 5;

// 4. Retornar estructura limpia para Moodle
return {
  json: {
    student_name: $('Build Prompt').item.json.student_name,
    filename: $('Build Prompt').item.json.filename,
    categorical_grade: gradeText,
    numeric_grade: numericGrade,
    markdown_report: rawText,
    raw_llm_response: response
  }
};
